import React from "react";
import { useState } from "react";
import "./taskflow.css";

function Taskflow() {
    const [search, setSearch] = useState("");
    const [newTask, setNewTask] = useState("");
    const [selectedId, setSelectedId] = useState(2);
    const [tasks, setTasks] = useState([""]);

    function addTask() {
        if (newTask.trim() === "") return;
        setTasks([
            ...tasks,
            { id: Date.now(), title: newTask, completed: false, createdAt: new Date().toDateString() },
        ]);
        setNewTask("");
    }

    function toggleTask(id) {
        setTasks(tasks.map((t) => (t.id === id ? { ...t, completed: !t.completed } : t)));
    }

    function editTask(id, oldTitle) {
        const title = prompt("Edit task:", oldTitle);
        if (title === null || title.trim() === "") return;
        setTasks(tasks.map((t) => (t.id === id ? { ...t, title: title } : t)));
    }

    function deleteTask(id) {
        setTasks(tasks.filter((t) => t.id !== id));
        if (selectedId === id) setSelectedId(null);
    }

    const filteredTasks = tasks.filter((t) =>
        t.title.toLowerCase().includes(search.toLowerCase())
    );

    const selectedTask = tasks.find((t) => t.id === selectedId);

    return (
        <div>
            <header className="header">
                <h1>TaskFlow</h1>
            </header>
            <div className="card">
                <h2>List View</h2>

                <input
                    className="text-box"
                    type="text"
                    placeholder="Search tasks..."
                    value={search}
                    onChange={(e) => setSearch(e.target.value)}
                />

                <div className="add-row">
                    <input
                        className="text-box"
                        type="text"
                        placeholder="Add a new task..."
                        value={newTask}
                        onChange={(e) => setNewTask(e.target.value)}
                    />
                    <button className="add-btn" onClick={addTask}>Add</button>
                </div>

                {filteredTasks.map((task) => (
                    <div className="task" key={task.id}>
                        <div>
                            <input
                                type="checkbox"
                                checked={task.completed}
                                onChange={() => toggleTask(task.id)}
                            />
                            <span
                                className={task.completed ? "title done" : "title"}
                                onClick={() => setSelectedId(task.id)}
                            >
                                {task.title}
                            </span>
                        </div>
                        <div className="task-buttons">
                            <button onClick={() => editTask(task.id, task.title)}>Edit</button>
                            <button onClick={() => deleteTask(task.id)}>Delete</button>
                        </div>
                    </div>
                ))}
            </div>

            {/* Detail View */}
            {selectedTask && (
                <div className="card">
                    <h2>Detail View</h2>

                    <p className="label">Title</p>
                    <p className="value">{selectedTask.title}</p>

                    <p className="label">Status</p>
                    <p className="value">{selectedTask.completed ? "Completed" : "Pending"}</p>

                    <p className="label">Created</p>
                    <p className="value">{selectedTask.createdAt}</p>

                    <div className="task-buttons">
                        <button onClick={() => toggleTask(selectedTask.id)}>
                            {selectedTask.completed ? "Mark as Pending" : "Mark as Completed"}
                        </button>
                        <button onClick={() => deleteTask(selectedTask.id)}>Delete</button>
                    </div>
                </div>
            )}
        </div>
    );
}

export default Taskflow
